head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDINF10000";
scwin.std_cd_apct_tp_cd = null;
scwin.reg_button = null;
scwin.dmenus = undefined;

///////// 2. 초기화 영역 /////////
// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — cfiCdGroupList5, cfiCdGroupList6, stdCdApctTpCdList, applId, acntNo, feeProcsStatCd

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "rd_group", fn: function(){ return (!(String(((dma_pageContext.get("cfiCdGroupList5") ?? "")) == null ? '' : ((dma_pageContext.get("cfiCdGroupList5") ?? ""))).length === 0)); } }, { id: "rd_group_2", fn: function(){ return (!(String(((dma_pageContext.get("cfiCdGroupList6") ?? "")) == null ? '' : ((dma_pageContext.get("cfiCdGroupList6") ?? ""))).length === 0)); } }, { id: "rd_stdCdApctTpCd", fn: function(){ return (!(String(((dma_pageContext.get("stdCdApctTpCdList") ?? "")) == null ? '' : ((dma_pageContext.get("stdCdApctTpCdList") ?? ""))).length === 0)); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_datefmt_cal_fornSecuIsuDd
 * @description 초기화 — datefmt cal forn Secu Isu Dd
 * @returns {void}
 * @hidden N
 */
scwin.init_datefmt_cal_fornSecuIsuDd = function () { $c.date.checkCalendarFormat("cal_fornSecuIsuDd", "yyyyMMdd"); };

/**
 * @method
 * @name init_datefmt_cal_continDeadlineStrtDd
