 * @returns {void}
 * @hidden N
 */
scwin.init_datefmt_cal_continDeadlineEndDd = function () { $c.date.checkCalendarFormat("cal_continDeadlineEndDd", "yyyyMMdd"); };

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        scwin.setFornsecucdComment();
        const cntr_iso_cd = '' + dma_companyInfoVO.get("cntrIsoCd") + '';
        if (cntr_iso_cd === "410") {
            $c.util.getComponent('ipt_domFornStkcertTpCd').setValue("D");
        } else {
            $c.util.getComponent('ipt_domFornStkcertTpCd').setValue("I");
        }
        scwin.setDomFornStkcertTpCd();
        if ((String(((dma_pageContext.get("applId") ?? "")) == null ? '' : ((dma_pageContext.get("applId") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("applId") ?? "")) == null ? '' : ((dma_pageContext.get("applId") ?? "")))) !== '') {
            await scwin.beforIsur((String(((dma_pageContext.get("applId") ?? "")) == null ? '' : ((dma_pageContext.get("applId") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("applId") ?? "")) == null ? '' : ((dma_pageContext.get("applId") ?? "")))));
            $c.util.getComponent("ipt_returnApplId").setValue((String(((dma_pageContext.get("applId") ?? "")) == null ? '' : ((dma_pageContext.get("applId") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("applId") ?? "")) == null ? '' : ((dma_pageContext.get("applId") ?? "")))));
            $c.util.getComponent("ipt_asumAcntNo").setValue((String(((dma_pageContext.get("acntNo") ?? "")) == null ? '' : ((dma_pageContext.get("acntNo") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("acntNo") ?? "")) == null ? '' : ((dma_pageContext.get("acntNo") ?? "")))));
            $c.util.getComponent("ipt_stdCdGrntFeeProcsStatCd").setValue((String(((dma_pageContext.get("feeProcsStatCd") ?? "")) == null ? '' : ((dma_pageContext.get("feeProcsStatCd") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("feeProcsStatCd") ?? "")) == null ? '' : ((dma_pageContext.get("feeProcsStatCd") ?? "")))));
        }
        const com_attr_tp_cd = '' + dma_companyInfoVO.get("comAttrTpCd") + '';
        if (com_attr_tp_cd === "5") {
            $c.util.getComponent("ipt_isuAmtK").setValue('0');
            $c.util.getComponent('ipt_isuAmtK').setStyle("background-color", '#e2e2e2');
            $c.util.getComponent('ipt_isuAmtK').setDisabled(true);
            $c.util.getComponent("ipt_isuAmtD").setValue('0');
            $c.util.getComponent('ipt_isuAmtD').setStyle("background-color", '#e2e2e2');
            $c.util.getComponent('ipt_isuAmtD').setDisabled(true);
            $c.util.getComponent("dma_sendFormReq").set("isuAmt", '0');
            $('input[name=group][value=E]').attr("checked", true);
            scwin.chg_group($("#group_E"));
        } else {
            $c.util.getComponent("ipt_isuAmtK").setValue('');
            $c.util.getComponent('ipt_isuAmtK').setStyle("background-color", '');
            $c.util.getComponent('ipt_isuAmtK').setDisabled(false);
            $c.util.getComponent("ipt_isuAmtD").setValue('');
            $c.util.getComponent('ipt_isuAmtD').setStyle("background-color", '');
            $c.util.getComponent('ipt_isuAmtD').setDisabled(false);
            $c.util.getComponent("dma_sendFormReq").set("isuAmt", '');
        }
        $("#group_C").attr("disabled", true);
        $("#group_Y").attr("disabled", true);
        $("#cal_continDeadlineStrtDd").datepicker("disable");
        $("#cal_continDeadlineEndDd").datepicker("disable");
        $("#ipt_stkcertKindC").on('click', function() {
                scwin.ctrl_stkcert_tp_rel_itm('C');
        });
        $("#ipt_stkcertKindP").on('click', function() {
                scwin.ctrl_stkcert_tp_rel_itm('P');
        });
        $("#ipt_stkcertKindM").on('click', function() {
                scwin.ctrl_stkcert_tp_rel_itm('M');
        });
        scwin.ctrl_stkcert_tp_rel_itm('C');

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf10000.onpageload' }); }
};

// [A] 초기 목록 미해결 — 진입 근거가 다른 액션을 가리킨다(fee vs stock) — 어느 쪽인지 정할 근거가 없다

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.dmenus ={
        "bmenu":2
        ,"mmenu":0
    }; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldinf10000' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.std_cd_apct_tp_cd = $c.util.getComponent('std_cd_apct_tp_cd');
        scwin.reg_button = $c.util.getComponent('reg_button');
        scwin.init_conds();
        scwin.init_datefmt_cal_fornSecuIsuDd();
        scwin.init_datefmt_cal_continDeadlineStrtDd();
        scwin.init_datefmt_cal_continDeadlineEndDd();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldinf10000.onpageload' });
    }
};

