scwin.chkMaxVal = async function (obj, max) { try { if (!obj || obj.value == null) { return; } const n = Number($c.num.unFormatNumber(String(obj.value))); if (isFinite(n) && Number(max) > 0 && n > Number(max)) { obj.value = String(max); await $c.win.alert('입력 가능한 최대값을 초과했습니다.'); } } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'authored-fn' }); return; } };

