/**
 * @method
 * @name beforIsur
 * @description befor Isur 처리
 * @param {String} applId applId
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.beforIsur = async function (applId) {
    let isur_cd = $c.util.getComponent('ipt_isurCd').getValue(); if (isur_cd == null) { isur_cd = ''; }
    if (isur_cd === '') {
        await $c.win.alert("발행기관 코드를 입력해 주세요.");
        return;
    }
    const url = "/stdcd/stock.do?method=bfReturnReAppl";
    const params = "isur_cd=" + isur_cd + "&applId=" + applId + "&menuId=10000";
    $.post(url, params, async function(obj) {
            if (obj === '') {
                await $c.win.alert("직전입력분 자료가 없습니다.");
            } else {
                const jsonData = (typeof obj === "string" ? (typeof obj === "string" ? JSON.parse(obj) : obj) : obj);
                $('input[name=r_dom_forn_stkcert_tp_cd][value="' + jsonData.dom_forn_stkcert_tp_cd + '"]').attr("checked", true);
                if ($("td#dom_forn_stkcert_tp_cd input:checked").val() === "D") {
                    $c.util.getComponent("ipt_fornSecuCd").setStyle("background", "#e2e2e2");
                    $c.util.getComponent('ipt_fornSecuCd').setDisabled(true);
                    scwin.setFornsecucdComment('D');
                    $c.util.getComponent('ipt_domFornStkcertTpCd').setValue("D");
                } else {
                    $c.util.getComponent("ipt_fornSecuCd").setStyle("background", "#FFFFFF");
                    $c.util.getComponent('ipt_fornSecuCd').setDisabled(false);
                    scwin.setFornsecucdComment('I');
                    $c.util.getComponent('ipt_domFornStkcertTpCd').setValue("I");
                }
                $c.util.getComponent('ipt_fornSecuCd').setValue(jsonData.forn_secu_cd);
                $c.util.getComponent('ipt_isuNm').setValue(jsonData.isu_nm);
                $c.util.getComponent('ipt_isuEngNm').setValue(jsonData.isu_eng_nm);
                if (jsonData.stkcert_kind_tp_cd === 'C') {
                    $("#ipt_stkcertKindC").trigger('click');
                } else {
                    if (jsonData.stkcert_kind_tp_cd === 'P') {
                        $("#ipt_stkcertKindP").trigger('click');
                    } else {
                        if (jsonData.stkcert_kind_tp_cd === 'M') {
                            $("#ipt_stkcertKindM").trigger('click');
                        }
                    }
                }
                $c.util.getComponent('slc_fornSecuKindCd').setValue(jsonData.forn_secu_kind_cd);
                $c.util.getComponent('cal_fornSecuIsuDd').setValue($c.date.dateFormat(jsonData.forn_secu_isu_dd));
                $('#slc_currTpCd').find('option[value="' + jsonData.curr_tp_cd + '"]').attr("selected", true);
                $c.util.getComponent('cal_continDeadlineStrtDd').setValue($c.date.dateFormat(jsonData.contin_deadline_strt_dd));
                $c.util.getComponent('cal_continDeadlineEndDd').setValue($c.date.dateFormat(jsonData.contin_deadline_end_dd));
                $c.util.getComponent('ipt_voterghtCnt').setValue(jsonData.voterght_cnt);
                scwin.fnOnchangeCurr();
                if (jsonData.curr_tp_cd === "1") {
                    $c.util.getComponent('ipt_isuAmtK').setValue(jsonData.isu_amt);
                    if (jsonData.isu_amt != null) {
                        $c.util.getComponent('txt_amtStr').setValue($c.num.formatNumberKor(String(((($('#ipt_isuAmtK')[0]) && ($('#ipt_isuAmtK')[0]).getValue) ? ($('#ipt_isuAmtK')[0]).getValue() : (((($('#ipt_isuAmtK')[0]) && typeof ($('#ipt_isuAmtK')[0]).val === 'function') ? ($('#ipt_isuAmtK')[0]).val() : ((($('#ipt_isuAmtK')[0]) && ($('#ipt_isuAmtK')[0]).value !== undefined) ? ($('#ipt_isuAmtK')[0]).value : ($('#ipt_isuAmtK')[0]))))) == null ? '' : ((($('#ipt_isuAmtK')[0]) && ($('#ipt_isuAmtK')[0]).getValue) ? ($('#ipt_isuAmtK')[0]).getValue() : (((($('#ipt_isuAmtK')[0]) && typeof ($('#ipt_isuAmtK')[0]).val === 'function') ? ($('#ipt_isuAmtK')[0]).val() : ((($('#ipt_isuAmtK')[0]) && ($('#ipt_isuAmtK')[0]).value !== undefined) ? ($('#ipt_isuAmtK')[0]).value : ($('#ipt_isuAmtK')[0])))))).replace(/,/g, '')));
                        $c.util.getComponent('ipt_isuAmtK').setValue($c.num.formatNumber($c.util.getComponent('ipt_isuAmtK').getValue()));
                    }
                } else {
                    $c.util.getComponent('ipt_isuAmtD').setValue(jsonData.isu_amt);
                }
                $('input[name=dom_forn_isu_tp_cd][value="' + jsonData.dom_forn_isu_tp_cd + '"]').attr("checked", true);
