/**
 * @method
 * @name checkNumUpperEnglish
 * @description check Num Upper English 처리
 * @param {*} aObj aObj
 * @param {*} aDesc aDesc
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkNumUpperEnglish = async function (aObj, aDesc) {
    const val = aObj.value;
    const len = val.length;
    for (let i = 0; i < len; i++) {
        const ch = val.charAt(i);
        const isNumEnglish = (ch >= '0' && ch <= '9') || (ch >= 'A' && ch <= 'Z');
        if (!isNumEnglish) {
            await $c.win.alert(aDesc + " - " + "숫자나 영문 대문자만 입력하십시오.");
            setTimeout(function() {
                    $("#glbl_isin_cd").select();
                }, 10);
            return false;
        }
    }
    return true;
};

/**
 * @method
 * @name chk_chrg_nm
 * @description chk chrg nm 처리
 * @param {*} fm fm
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.chk_chrg_nm = async function (fm) {
    const len = $c.str.getByteLength(fm.chrg_nm.value);
    if (len > 20) {
        await $c.win.alert("이름은 한글10자, 영문20자 이내로 입력하세요.");
        chrg_nm.focus();
        return;
    }
};
